package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the statement, once it is saved. */
public class AuditStatement {
    public void audit(@Val Statement statement, @Val Person person,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        audit.record("STATEMENT sheet=" + statement.getSheetId() + " by=" + AuditUser.decode(user)
                + " name=" + person.getName() + " due-total=" + statement.getDueTotal()
                + " claims=" + statement.getClaims());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Transient;
import java.time.LocalDate;

/** A statement taken for a person: their due-total then (two decimals, or n/a) and the sheet's today then. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "due_total", nullable = false)
    private String dueTotal;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    /** How many of the person's claims counted, and so were bound; for the audit only. */
    @Transient
    private int claims;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, String dueTotal, LocalDate takenOn, int claims) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.takenOn = takenOn;
        this.claims = claims;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public String getDueTotal() {
        return dueTotal;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public int getClaims() {
        return claims;
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements, oldest first. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** The person's statements, oldest first. */
    List<Statement> findByPersonIdOrderByIdAsc(Long personId);
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement for the person: records their due-total now, on the sheet's today, and binds each of
 * their claims that counts to the figure it has now (never its late charge, which keeps following the sheet's today); their claims that do not count (a person's unbound OPEN ones dated within a
 * hold among them) are unbound (live again).
 */
public class TakeStatement {
    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            StatementRepository statements, EntityManager entityManager, Out<Statement> statementOut) {
        // Lock the person so two statements (or a statement and an edit) are taken one after the other.
        entityManager.refresh(person, LockModeType.PESSIMISTIC_WRITE);
        List<Claim> mine = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheet.getId(), person.getId());
        ClaimFigures figures = new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheet.getId()),
                grades.gradesOf(person), sheet);
        String dueTotal = figures.dueTotal(mine, sheet.getToday(), person);
        int counted = 0;
        for (Claim claim : mine) {
            if (ClaimFigures.countsLive(claim, person, sheet.getToday())) {
                BigDecimal figure = figures.figure(claim);
                claim.bind(true, figure);
                counted++;
            } else {
                claim.bind(false, null);
            }
        }
        claims.saveAllAndFlush(mine);
        statementOut.set(statements.save(
                new Statement(sheet.getId(), person.getId(), dueTotal, sheet.getToday(), counted)));
    }
}
-- A person's statement: their due-total when it was taken (n/a when there was none) and the sheet's
-- today then. Their count and last one are read from here.
CREATE TABLE statement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    due_total VARCHAR(30) NOT NULL,
    taken_on DATE NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due;
-- null when it had none, n/a), until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
