package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClerkLimit {
    public void handle(@Parameter ClerkLimitException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.FORBIDDEN));
    }
}
package net.officefloor.hq.app.claim;

/** A clerk doing what only a steward may: approving or rejecting a PENDING claim. */
public class ClerkLimitException extends Exception {
    public ClerkLimitException(String message) {
        super(message);
    }
}
import { useRef, useSyncExternalStore } from 'react';

// The last action taken on each row, by row key. A row's cells come from separate slots, each with its own
// mutation; an error belongs to the action that raised it, so it is shown only while that action is still the
// row's latest — taking the next action on the row, in any of its cells, removes an old error.
const latest = new Map<string, symbol>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}

export function useRowAction(row: string) {
  const mine = useRef(Symbol(row));
  const current = useSyncExternalStore(subscribe, () => latest.get(row));
  return {
    /** Marks this cell's action as the row's latest; call it as the action is taken. */
    take: () => {
      latest.set(row, mine.current);
      listeners.forEach((l) => l());
    },
    /** Whether this cell's action is the row's latest, so its error may show. */
    isLatest: current === mine.current,
  };
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Long id;
        try {
            id = Long.valueOf(personId.trim());
        } catch (NumberFormatException e) {
            throw new PersonNotFoundException(personId);
        }
        personOut.set(repository.findByIdAndSheetId(id, sheetId.trim())
                .orElseThrow(() -> new PersonNotFoundException(personId)));
    }
}

